typography-bar.snippet:
.typography-bar
display: inline-block;
box-sizing: border-box;
font-family: var(--eds-family-sans); /* "EDS Text", "PingFang SC", SourceHanSansSC, "Apple Color Emoji", "Segoe UI Emoji" */
font-size: calc(var(--eds-bar-size) * 2);
font-weight: var(--eds-bar-weight); /* 500 */
line-height: calc(var(--eds-bar-line-height) * 2);
transform: scale(0.5);
transform-origin: top center;
margin-bottom: calc(var(--eds-bar-line-height) * -1);
-webkit-font-smoothing: antialiased;
-moz-osx-font-smoothing: grayscale;

motion-menu.snippet:
.motion-menu
transition: var(--motion-recipe-menu);
transform: scale(1);
opacity: var(--motion-opacity-visible);

motion-sheets.snippet:
.motion-sheets
transition: var(--motion-recipe-sheets);
transform: translateY(0);
left: var(--motion-offset-sheets-inset);
right: var(--motion-offset-sheets-inset);
bottom: var(--motion-offset-sheets-inset);
border-radius: var(--motion-radius-sheets-floating);
